"use client";

import { useState, useCallback, useRef, useEffect } from "react";
import { Program as Motely } from "motely-wasm/motely/wasm";
import type { IMotelySearch, MotelyProgress, MotelyScoredSeedResult } from "motely-wasm/motely";
import type { JamlAesthetic } from "motely-wasm/motely/filters/jaml";
import { ensureMotelyReady, setJimmolateProbe, clearJimmolateProbe, type JimmolateProbe } from "../lib/motely/runtime.js";

export interface SearchResult {
    seed: string;
    score: number;
    tallyColumns?: number[];
}

export type SearchMode = "aesthetic" | "seedlist" | "random";
export type SearchStatus = "idle" | "running" | "completed" | "cancelled" | "error";

export interface UseSearchState {
    results: SearchResult[];
    totalSearched: bigint;
    matchingSeeds: bigint;
    status: SearchStatus;
    error: string | null;
    seedsPerSecond: number;
    tallyLabels: string[];
}

const INITIAL_STATE: UseSearchState = {
    results: [],
    totalSearched: 0n,
    matchingSeeds: 0n,
    status: "idle",
    error: null,
    seedsPerSecond: 0,
    tallyLabels: [],
};


// motely-wasm 21: Program.run*Search EXECUTES the search synchronously to
// completion (WASM has no pthreads — the engine documents that every Run* call
// blocks the calling thread) and returns the finished IMotelySearch. So this
// both selects the mode AND runs it; events fire during the call.
function runConfigured(jaml: string, mode: SearchMode, opts: { aesthetic?: number; seeds?: string[]; count?: number }): IMotelySearch {
    const config = Motely.fromYaml(jaml);
    if (mode === "seedlist" && opts.seeds && opts.seeds.length > 0) {
        config.seeds = opts.seeds;
        return Motely.runSeedListSearch(config);
    }
    if (mode === "random" && typeof opts.count === "number" && opts.count > 0) {
        return Motely.runRandomSearch(config, opts.count);
    }
    return Motely.runAestheticSearch(config, (opts.aesthetic ?? 0) as JamlAesthetic);
}

export function useSearch() {
    const [state, setState] = useState<UseSearchState>(INITIAL_STATE);
    const searchRef = useRef<IMotelySearch | null>(null);
    const cleanupRef = useRef<(() => void) | null>(null);

    const teardown = useCallback(() => {
        cleanupRef.current?.();
        cleanupRef.current = null;
        searchRef.current?.cancel();
        searchRef.current = null;
    }, []);

    useEffect(() => () => teardown(), [teardown]);

    // The jimmolate `predicate` (motely-wasm >=21.1 shape) receives the scored
    // result ({seed, score, tallies}) and decides whether it counts as a match.
    const startSearch = useCallback(
        async (jaml: string, mode: SearchMode, opts: { aesthetic?: number; seeds?: string[]; count?: number; predicate?: JimmolateProbe } = {}) => {
            try {
                await ensureMotelyReady();

                let validation = "valid";
                try { Motely.fromYaml(jaml); } catch (e) { validation = e instanceof Error ? e.message : "Invalid JAML"; }
                if (validation !== "valid") {
                    setState((s) => ({ ...s, status: "error", error: validation }));
                    return;
                }

                teardown();

                setState({ ...INITIAL_STATE, status: "running" });

                // Yield one macrotask BEFORE subscribing, so React paints the
                // "running" state and there is no await between subscribe and
                // the synchronous run — a rapid double startSearch() can no
                // longer cross-unsubscribe the other call's listeners mid-gap.
                await new Promise((resolve) => setTimeout(resolve, 0));

                const onResult = (result: MotelyScoredSeedResult) => {
                    setState((s) => ({
                        ...s,
                        results: [...s.results, {
                            seed: result.seed,
                            score: result.score,
                            tallyColumns: Array.from(result.tallies),
                        }].slice(0, 1000),
                    }));
                };
                Motely.onScoredResult.subscribe(onResult);

                const onProgress = (progress: MotelyProgress) => {
                    const elapsedSec = Number(progress.elapsedMilliseconds) / 1000;
                    const sps = elapsedSec > 0 ? Number(progress.seedsSearched) / elapsedSec : 0;
                    setState((s) => ({
                        ...s,
                        totalSearched: progress.seedsSearched,
                        matchingSeeds: progress.matchingSeeds,
                        seedsPerSecond: sps,
                    }));
                };
                Motely.onProgress.subscribe(onProgress);

                cleanupRef.current = () => {
                    Motely.onScoredResult.unsubscribe(onResult);
                    Motely.onProgress.unsubscribe(onProgress);
                };

                if (opts.predicate) {
                    setJimmolateProbe(opts.predicate);
                    Motely.jimmolateEnabled = true;
                }

                try {
                    const search = runConfigured(jaml, mode, opts);
                    searchRef.current = search;
                    setState((s) => ({
                        ...s,
                        status: search.isCompleted ? "completed" : "cancelled",
                        totalSearched: search.totalSeedsSearched,
                        matchingSeeds: search.matchingSeeds,
                        seedsPerSecond: 0,
                    }));
                } finally {
                    if (opts.predicate) {
                        Motely.jimmolateEnabled = false;
                        clearJimmolateProbe();
                    }
                    cleanupRef.current?.();
                    cleanupRef.current = null;
                    searchRef.current = null;
                }
            } catch (error) {
                Motely.jimmolateEnabled = false;
                clearJimmolateProbe();
                teardown();
                const message = error instanceof Error ? error.message : String(error);
                setState((s) => ({ ...s, status: "error", error: message, seedsPerSecond: 0 }));
            }
        },
        [teardown],
    );

    const startAesthetic = useCallback(
        (jaml: string, aesthetic: number, predicate?: JimmolateProbe) =>
            startSearch(jaml, "aesthetic", { aesthetic, predicate }),
        [startSearch],
    );

    const startSeedList = useCallback(
        (jaml: string, seeds: string[], predicate?: JimmolateProbe) =>
            startSearch(jaml, "seedlist", { seeds, predicate }),
        [startSearch],
    );

    const startRandom = useCallback(
        (jaml: string, count: number, predicate?: JimmolateProbe) =>
            startSearch(jaml, "random", { count, predicate }),
        [startSearch],
    );

    const cancel = useCallback(() => {
        searchRef.current?.cancel();
        setState((s) => ({ ...s, status: "cancelled", seedsPerSecond: 0 }));
    }, []);

    const reset = useCallback(() => {
        teardown();
        setState(INITIAL_STATE);
    }, [teardown]);

    const clearError = useCallback(() => {
        setState((s) => (s.error || s.status === "error" ? { ...s, error: null, status: "idle" } : s));
    }, []);

    return {
        ...state,
        startAesthetic,
        startSeedList,
        startRandom,
        cancel,
        reset,
        clearError,
    };
}
