// CodeMirror 6 ⇆ jaml-lang bridge.
//
// jaml-lang (published npm pkg) is the single source of truth for JAML
// completions + diagnostics + hover, generated from the Motely C# enums. This
// file is a thin adapter that maps its editor-agnostic, LSP-shaped API onto
// CodeMirror's autocomplete + lint + hover extensions. No JAML knowledge lives
// here — it all comes from jaml-lang.
//
// jaml-lang 1.0.0 API: getDiagnostics/getCompletions/getHover return LSP-shaped
// data; diagnostic severity is the raw LSP number (1=Error, 2=Warning, 3=Info,
// 4=Hint) — there is no Severity enum (that was 0.1.x).

import type { CompletionContext, CompletionResult, Completion } from "@codemirror/autocomplete";
import { linter, type Diagnostic as CMDiagnostic } from "@codemirror/lint";
import { hoverTooltip, type Tooltip } from "@codemirror/view";
import type { Text } from "@codemirror/state";
import { getCompletions, getDiagnostics, getHover, type CompletionKind } from "jaml-lang";

// jaml-lang completion kind -> CodeMirror completion `type` (drives the icon/color).
function kindToType(kind: CompletionKind): Completion["type"] {
  switch (kind) {
    case "field": return "property";
    case "enum": return "enum";
    case "value": return "constant";
    case "keyword": return "keyword";
    default: return "text";
  }
}

/**
 * CodeMirror completion source backed by jaml-lang's context-aware completions.
 * Tap into `joker: ` and you get the joker list; type `Blue` and it narrows to
 * Blueprint. Keys insert `label: `, values insert the bare value.
 */
export function jamlCompletionSource(context: CompletionContext): CompletionResult | null {
  const word = context.matchBefore(/[\w-]*/);
  // Don't pop up on an empty line unless the user explicitly asked (Ctrl-Space).
  if (!context.explicit && word && word.from === word.to) return null;

  const items = getCompletions(context.state.doc.toString(), context.pos);
  if (items.length === 0) return null;

  const options: Completion[] = items.map((it) => ({
    label: it.label,
    type: kindToType(it.kind),
    detail: it.detail,
    info: it.documentation,
    apply: it.insertText ?? it.label,
  }));

  return {
    from: word ? word.from : context.pos,
    options,
    validFor: /^[\w-]*$/,
  };
}

// LSP 0-based {line, character} -> CodeMirror absolute offset, clamped to bounds.
function posToOffset(doc: Text, line: number, character: number): number {
  if (line < 0) return 0;
  if (line >= doc.lines) return doc.length;
  const l = doc.line(line + 1);
  return Math.min(l.from + Math.max(0, character), l.to);
}

/**
 * CodeMirror lint source backed by jaml-lang diagnostics (YAML syntax + the
 * generated structural validation). The Motely WASM engine stays the final
 * authority; this is the fast structural gate. Severity is the raw LSP number.
 */
export const jamlLinter = linter((view): CMDiagnostic[] => {
  const doc = view.state.doc;
  return getDiagnostics(doc.toString()).map((d): CMDiagnostic => ({
    from: posToOffset(doc, d.range.start.line, d.range.start.character),
    to: posToOffset(doc, d.range.end.line, d.range.end.character),
    severity: d.severity === 1 ? "error" : d.severity === 2 ? "warning" : "info",
    message: d.message,
    source: d.source,
  }));
});

// Minimal, XSS-safe markdown for jaml-lang hovers: escape HTML, then render the
// only two markers jaml-lang emits — **bold** and `code`.
function renderHoverMarkdown(md: string): string {
  const esc = md.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  return esc
    .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
    .replace(/`([^`]+)`/g, "<code>$1</code>");
}

/**
 * CodeMirror hover backed by jaml-lang's getHover — explains the key/enum member
 * under the cursor (e.g. hover `joker` or `Blueprint`). Contents are light
 * markdown ("**word** — detail"); rendered (bold + code) into the tooltip dom.
 */
export const jamlHoverTooltip = hoverTooltip((view, pos): Tooltip | null => {
  const doc = view.state.doc;
  const h = getHover(doc.toString(), pos);
  if (!h) return null;
  const from = h.range ? posToOffset(doc, h.range.start.line, h.range.start.character) : pos;
  const to = h.range ? posToOffset(doc, h.range.end.line, h.range.end.character) : pos;
  return {
    pos: from,
    end: to,
    above: true,
    create() {
      const dom = document.createElement("div");
      dom.className = "cm-jaml-hover";
      // Render jaml-lang's light markdown ("**bold**", `code`) — HTML-escaped first,
      // then bold/code spans. Not stripped — the formatting IS the signal.
      dom.innerHTML = renderHoverMarkdown(h.contents);
      return { dom };
    },
  };
});
